,WAAW,CAAG,sBAC3Bd,SAAS6C,KAAK,CAACC,OAAO,CAAG,eACzB9C,SAAS+F,gBAAgB,CAAC,QAASnD,aAEvC","names":["MP","POSE","diag","document","getElementById","msg","startBtn","badge","hud","fpsEl","kpEl","v","c","landmarker","stream","lastTs","frameCount","lastFpsAt","setDiag","t","textContent","initEngine","WebAssembly","instantiate","Uint8Array","e","message","innerHTML","lastErr","delegates","i","length","vision","fileset","FilesetResolver","forVisionTasks","resp","fetch","ok","Error","status","buf","arrayBuffer","PoseLandmarker","createFromOptions","baseOptions","modelAssetBuffer","delegate","runningMode","numPoses","startCamera","style","display","srcObject","navigator","mediaDevices","getUserMedia","video","facingMode","width","height","audio","play","$","performance","now","drawLoop","vw","videoWidth","vh","videoHeight","ctx","getContext","readyState","clearRect","ts","res","detectForVideo","pts","landmarks","vis","lineWidth","strokeStyle","a","b","beginPath","moveTo","x","y","lineTo","stroke","fillStyle","k","p","visibility","arc","Math","PI","fill","round","requestAnimationFrame","addEventListener"],"ignoreList":[],"sources":["../../src/client/poselive.ts"],"sourcesContent":["// Standalone live pose-tracking entry (classic UI page, outside the Polaris/UXF shell).
// Plain DOM + MediaPipe BlazePose. Writes engine-init result to #diag for headless verification.
const MP = "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.18";
const MODEL = "https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/1/pose_landmarker_lite.task";
const POSE: number[][] = [[11,12],[11,13],[13,15],[12,14],[14,16],[15,17],[15,19],[16,18],[16,20],[11,23],[12,24],[23,24],[23,25],[25,27],[27,29],[27,31],[24,26],[26,28],[28,30],[28,32],[0,11],[0,12]];

const $ = (id: string): any => document.getElementById(id);
const diag = $("diag"), msg = $("msg"), startBtn = $("startBtn"), badge = $("badge"), hud = $("hud");
const fpsEl = $("fps"), kpEl = $("kp"), v: any = $("v"), c: any = $("c");

let landmarker: any = null, stream: any = null, lastTs = 0, frameCount = 0, lastFpsAt = 0;

function setDiag(t: string) { if (diag) diag.textContent = t; }

async function initEngine(): Promise<boolean> {
  try { await WebAssembly.instantiate(new Uint8Array([0, 97, 115, 109, 1, 0, 0, 0])); }
  catch (e: any) { setDiag("WASM_FAIL " + (e && e.message ? e.message : e)); if (msg) msg.innerHTML = '<span class="err">WebAssembly is blocked on this page.</span>'; return false; }

  let lastErr = "";
  const delegates = ["GPU", "CPU"];
  for (let i = 0; i < delegates.length; i++) {
    try {
      const vision: any = await import(/* @vite-ignore */ (MP + "/vision_bundle.mjs"));
      const fileset = await vision.FilesetResolver.forVisionTasks(MP + "/wasm");
      const resp = await fetch(MODEL);
      if (!resp.ok) throw new Error("model HTTP " + resp.status);
      const buf = new Uint8Array(await resp.arrayBuffer());
      landmarker = await vision.PoseLandmarker.createFromOptions(fileset, { baseOptions: { modelAssetBuffer: buf, delegate: delegates[i] }, runningMode: "VIDEO", numPoses: 1 });
      setDiag("POSE_INIT_OK_" + delegates[i]);
      return true;
    } catch (e: any) { lastErr = (e && e.message ? e.message : "" + e); }
  }
  setDiag("POSE_INIT_FAIL " + lastErr);
  if (msg) msg.innerHTML = '<span class="err">Pose engine could not start:<br>' + lastErr + '</span>';
  return false;
}

function drawLoop() {
  if (!landmarker || !stream) return;
  const vw = v.videoWidth || 0, vh = v.videoHeight || 0;
  if (vw && c.width !== vw) { c.width = vw; c.height = vh; }
  const ctx = c.getContext("2d");
  if (ctx && vw && v.readyState >= 2) {
    ctx.clearRect(0, 0, vw, vh);
    try {
      let ts = performance.now(); if (ts <= lastTs) ts = lastTs + 1; lastTs = ts;
      const res = landmarker.detectForVideo(v, ts);
      const pts = res && res.landmarks && res.landmarks[0];
      if (pts) {
        let vis = 0;
        ctx.lineWidth = 3; ctx.strokeStyle = "#35e0ff";
        for (let e = 0; e < POSE.length; e++) {
          const a = pts[POSE[e][0]], b = pts[POSE[e][1]];
          if (a && b) { ctx.beginPath(); ctx.moveTo(a.x * vw, a.y * vh); ctx.lineTo(b.x * vw, b.y * vh); ctx.stroke(); }
        }
        ctx.fillStyle = "#34e3a4";
        for (let k = 0; k < pts.length; k++) { const p = pts[k]; if (p.visibility == null || p.visibility > 0.5) vis++; ctx.beginPath(); ctx.arc(p.x * vw, p.y * vh, 4, 0, Math.PI * 2); ctx.fill(); }
        if (kpEl) kpEl.textContent = "" + vis;
      }
    } catch (e) { /* non-fatal */ }
  }
  frameCount++; const now = performance.now();
  if (now - lastFpsAt > 500) { if (fpsEl) fpsEl.textContent = "" + Math.round(frameCount * 1000 / (now - lastFpsAt)); frameCount = 0; lastFpsAt = now; }
  requestAnimationFrame(drawLoop);
}

async function startCamera() {
  startBtn.style.display = "none";
  if (msg) msg.textContent = "Starting camera…";
  try {
    stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user", width: 640, height: 480 }, audio: false });
    v.srcObject = stream;
    await v.play();
    $("overlay").style.display = "none";
    badge.style.display = "flex";
    hud.style.display = "flex";
    $("badgeText").textContent = "LIVE · TRACKING";
    lastFpsAt = performance.now();
    drawLoop();
  } catch (e: any) {
    if (msg) msg.innerHTML = '<span class="err">Camera error: ' + (e && e.message ? e.message : e) + '</span>';
    $("overlay").style.display = "flex";
  }
}

(async function () {
  const ok = await initEngine();
  if (ok) {
    if (msg) msg.textContent = "Pose engine ready.";
    startBtn.style.display = "inline-block";
    startBtn.addEventListener("click", startCamera);
  }
})();

export {};
"]}
